import XCTest

class SettingsTest: XCTestCase {
    override func setUp() {
        super.setUp()
        continueAfterFailure = false
    }

    func testNavigateToPrivacySecurity() {
        let app = XCUIApplication(bundleIdentifier: "com.apple.Preferences")
        app.launch()
        sleep(2)

        // Try to find and tap Privacy & Security
        let privacyElement = app.staticTexts["Privacy & Security"]
        if privacyElement.exists {
            privacyElement.tap()
            sleep(2)
        }
    }
}
EOF

